"use client";

import { useState, useEffect } from "react";
import { useRouter, useParams } from "next/navigation";
import { db } from "../../../firebase";
import { doc, getDoc, collection, addDoc, getDocs } from "firebase/firestore";

export default function JobDetailsPage() {
  const params = useParams();
  const [job, setJob] = useState<any>(null);
  const [message, setMessage] = useState<string>("");

  // Invoice States
  const [invoiceNumber, setInvoiceNumber] = useState<string>("");
  const [stage, setStage] = useState<string>("deposit");
  const [invoices, setInvoices] = useState<any[]>([]);

  // Expense and Material States
  const [expenses, setExpenses] = useState<any[]>([]);
  const [materials, setMaterials] = useState<any[]>([]);
  const [totalExpenses, setTotalExpenses] = useState<number>(0);
  const [totalMaterials, setTotalMaterials] = useState<number>(0);

  // Placeholder for Labor Costs (to be linked with timesheets later)
  const [laborCosts, setLaborCosts] = useState<number>(0);

  // New Expense and Material Inputs
  const [newExpenseInvoiceNumber, setNewExpenseInvoiceNumber] = useState<string>("");
  const [newExpenseSupplier, setNewExpenseSupplier] = useState<string>("");
  const [newExpenseDescription, setNewExpenseDescription] = useState<string>("");
  const [newExpenseAmount, setNewExpenseAmount] = useState<number>(0);

  const [newMaterialInvoiceNumber, setNewMaterialInvoiceNumber] = useState<string>("");
  const [newMaterialSupplier, setNewMaterialSupplier] = useState<string>("");
  const [newMaterialDescription, setNewMaterialDescription] = useState<string>("");
  const [newMaterialAmount, setNewMaterialAmount] = useState<number>(0);

  const router = useRouter();

  useEffect(() => {
    const fetchJobDetails = async () => {
      try {
        const docRef = doc(db, "jobs", params.id);
        const docSnap = await getDoc(docRef);
        if (docSnap.exists()) {
          setJob({ id: docSnap.id, ...docSnap.data() });
        } else {
          setMessage("Job not found.");
        }
      } catch (error) {
        console.error("Error fetching job details:", error);
        setMessage("Failed to load job details.");
      }
    };
    fetchJobDetails();
    fetchInvoices();
    fetchExpensesAndMaterials();
  }, [params.id]);

  // Add Invoice
  const addInvoice = async () => {
    if (!invoiceNumber) {
      setMessage("Please enter the invoice number.");
      return;
    }

    try {
      await addDoc(collection(db, "jobs", params.id, "invoices"), {
        stage,
        invoiceNumber,
      });
      setMessage("Invoice added successfully!");
      setInvoiceNumber("");
      fetchInvoices();
    } catch (error) {
      console.error("Error adding invoice:", error);
      setMessage("Failed to add invoice.");
    }
  };

  // Fetch Invoices
  const fetchInvoices = async () => {
    try {
      const invoicesSnap = await getDocs(collection(db, "jobs", params.id, "invoices"));
      const invoiceList = invoicesSnap.docs.map((doc) => doc.data());
      setInvoices(invoiceList);
    } catch (error) {
      console.error("Error fetching invoices:", error);
      setMessage("Failed to load invoices.");
    }
  };

  // Fetch Expenses and Materials
  const fetchExpensesAndMaterials = async () => {
    try {
      const expensesSnap = await getDocs(collection(db, "jobs", params.id, "expenses"));
      const materialsSnap = await getDocs(collection(db, "jobs", params.id, "materials"));

      const expList = expensesSnap.docs.map((doc) => doc.data());
      const matList = materialsSnap.docs.map((doc) => doc.data());

      setExpenses(expList);
      setMaterials(matList);

      // Calculate Totals
      const totalExp = expList.reduce((acc, item) => acc + (item.amount || 0), 0);
      const totalMat = matList.reduce((acc, item) => acc + (item.amount || 0), 0);

      setTotalExpenses(totalExp);
      setTotalMaterials(totalMat);
    } catch (error) {
      console.error("Error fetching expenses or materials:", error);
    }
  };

  // Add Expense
  const addExpense = async () => {
    if (!newExpenseInvoiceNumber || !newExpenseSupplier || !newExpenseDescription || newExpenseAmount <= 0) {
      setMessage("Please provide all fields for the expense.");
      return;
    }

    try {
      await addDoc(collection(db, "jobs", params.id, "expenses"), {
        invoiceNumber: newExpenseInvoiceNumber,
        supplier: newExpenseSupplier,
        description: newExpenseDescription,
        amount: newExpenseAmount,
      });
      setMessage("Expense added successfully!");
      setNewExpenseInvoiceNumber("");
      setNewExpenseSupplier("");
      setNewExpenseDescription("");
      setNewExpenseAmount(0);
      fetchExpensesAndMaterials();
    } catch (error) {
      console.error("Error adding expense:", error);
      setMessage("Failed to add expense.");
    }
  };

  // Add Material
  const addMaterial = async () => {
    if (!newMaterialInvoiceNumber || !newMaterialSupplier || !newMaterialDescription || newMaterialAmount <= 0) {
      setMessage("Please provide all fields for the material.");
      return;
    }

    try {
      await addDoc(collection(db, "jobs", params.id, "materials"), {
        invoiceNumber: newMaterialInvoiceNumber,
        supplier: newMaterialSupplier,
        description: newMaterialDescription,
        amount: newMaterialAmount,
      });
      setMessage("Material added successfully!");
      setNewMaterialInvoiceNumber("");
      setNewMaterialSupplier("");
      setNewMaterialDescription("");
      setNewMaterialAmount(0);
      fetchExpensesAndMaterials();
    } catch (error) {
      console.error("Error adding material:", error);
      setMessage("Failed to add material.");
    }
  };

  return (
    <div className="p-6">
      <h1 className="text-xl font-bold mb-4">Job Details</h1>
      {message && <p className="mb-2 text-green-600">{message}</p>}
      <div className="border p-4 rounded mb-4">
        <p className="font-semibold">Address: {job?.jobAddress}</p>
        <p>Customer: {job?.customerName}</p>
        <p>Description: {job?.jobDescription}</p>
        <p>Quote Number: {job?.quoteNumber}</p>
        <p>Budget: ${job?.budget}</p>
        <p>Status: {job?.status}</p>
      </div>

      {/* Labor Costs (Placeholder for Timesheet Integration) */}
      <h2 className="text-lg font-semibold mb-2">Labor Costs (Total: ${laborCosts})</h2>
      <p>This section will be updated once timesheet integration is set up.</p>

      {/* Invoice Section */}
      <h2 className="text-lg font-semibold mb-2">Invoices</h2>
      {invoices.map((invoice, index) => (
        <div key={index} className="border p-2 mb-2 rounded">
          <p>Stage: {invoice.stage}</p>
          <p>Invoice Number: {invoice.invoiceNumber}</p>
        </div>
      ))}
      <h3 className="text-md font-semibold mt-4">Add Invoice</h3>
      <select
        value={stage}
        onChange={(e) => setStage(e.target.value)}
        className="border rounded p-2 w-full mb-2"
      >
        <option value="deposit">Deposit</option>
        <option value="progress">Progress</option>
        <option value="final">Final</option>
      </select>
      <input
        type="text"
        placeholder="Invoice Number"
        value={invoiceNumber}
        onChange={(e) => setInvoiceNumber(e.target.value)}
        className="border rounded p-2 w-full mb-2"
      />
      <button onClick={addInvoice} className="px-4 py-2 bg-blue-600 text-white rounded mb-4">Add Invoice</button>

      {/* Add Expense Section */}
      <h2 className="text-lg font-semibold mb-2">Add Expense</h2>
      <input
        type="text"
        placeholder="Invoice Number"
        value={newExpenseInvoiceNumber}
        onChange={(e) => setNewExpenseInvoiceNumber(e.target.value)}
        className="border rounded p-2 w-full mb-2"
      />
      <input
        type="text"
        placeholder="Supplier"
        value={newExpenseSupplier}
        onChange={(e) => setNewExpenseSupplier(e.target.value)}
        className="border rounded p-2 w-full mb-2"
      />
      <input
        type="text"
        placeholder="Description"
        value={newExpenseDescription}
        onChange={(e) => setNewExpenseDescription(e.target.value)}
        className="border rounded p-2 w-full mb-2"
      />
      <input
        type="number"
        placeholder="Amount"
        value={newExpenseAmount}
        onChange={(e) => setNewExpenseAmount(Number(e.target.value))}
        className="border rounded p-2 w-full mb-2"
      />
      <button onClick={addExpense} className="px-4 py-2 bg-green-600 text-white rounded mb-4">Add Expense</button>

      {/* Add Material Section */}
      <h2 className="text-lg font-semibold mb-2">Add Material</h2>
      <input
        type="text"
        placeholder="Invoice Number"
        value={newMaterialInvoiceNumber}
        onChange={(e) => setNewMaterialInvoiceNumber(e.target.value)}
        className="border rounded p-2 w-full mb-2"
      />
      <input
        type="text"
        placeholder="Supplier"
        value={newMaterialSupplier}
        onChange={(e) => setNewMaterialSupplier(e.target.value)}
        className="border rounded p-2 w-full mb-2"
      />
      <input
        type="text"
        placeholder="Description"
        value={newMaterialDescription}
        onChange={(e) => setNewMaterialDescription(e.target.value)}
        className="border rounded p-2 w-full mb-2"
      />
      <input
        type="number"
        placeholder="Amount"
        value={newMaterialAmount}
        onChange={(e) => setNewMaterialAmount(Number(e.target.value))}
        className="border rounded p-2 w-full mb-2"
      />
      <button onClick={addMaterial} className="px-4 py-2 bg-blue-600 text-white rounded mb-4">Add Material</button>

      {/* Expenses and Materials Section */}
      <h2 className="text-lg font-semibold mb-2">Expenses (Total: ${totalExpenses})</h2>
      {expenses.map((expense, index) => (
        <p key={index}>{expense.description} - ${expense.amount}</p>
      ))}
      <h2 className="text-lg font-semibold mb-2">Materials (Total: ${totalMaterials})</h2>
      {materials.map((material, index) => (
        <p key={index}>{material.description} - ${material.amount}</p>
      ))}

      <div className="mt-4">
        <button onClick={() => router.push("/add-job")} className="px-4 py-2 bg-blue-600 text-white rounded">
          Save and Close
        </button>
      </div>
    </div>
  );
}
